import javax.tools.*;import java.nio.file.*;import java.net.*;import java.lang.reflect.*;
class TestNativeUpdate{public static void main(String[] args)throws Exception{Path out=Files.createTempDirectory("wird-version-");int status=ToolProvider.getSystemJavaCompiler().run(null,null,null,"-d",out.toString(),args[0]);if(status!=0)throw new Exception("compile failed");try(URLClassLoader loader=new URLClassLoader(new URL[]{out.toUri().toURL()})){Class<?> c=Class.forName("com.wird.app.UpdateVersion",true,loader);Method m=c.getDeclaredMethod("compare",String.class,String.class);m.setAccessible(true);String[][] rows={{"75.75","75.74","1"},{"v75.100","75.99","1"},{"75.74","75.74","0"},{"75.73","75.74","-1"},{"75.74.1","75.74","1"},{"75.75-beta","75.74","0"}};for(String[] r:rows)if(Integer.signum((int)m.invoke(null,r[0],r[1]))!=Integer.parseInt(r[2]))throw new Exception("bad version ordering");System.out.println("Native Java version ordering passed");}}}
